import java.util.*;

public class Main {
    static long manhattan(long x1, long y1, long x2, long y2) {
        return Math.abs(x1 - x2) + Math.abs(y1 - y2);
    }

    static long pointRectDist(long px, long py, long x1, long y1, long x2, long y2) {
        long dx = 0, dy = 0;
        if (px < x1) dx = x1 - px;
        else if (px > x2) dx = px - x2;
        if (py < y1) dy = y1 - py;
        else if (py > y2) dy = py - y2;
        return dx + dy;
    }

    static long rectDist(int i, int j, long[] x1, long[] y1, long[] x2, long[] y2) {
        long dx = 0, dy = 0;
        if (x2[i] < x1[j]) dx = x1[j] - x2[i];
        else if (x2[j] < x1[i]) dx = x1[i] - x2[j];

        if (y2[i] < y1[j]) dy = y1[j] - y2[i];
        else if (y2[j] < y1[i]) dy = y1[i] - y2[j];

        return dx + dy;
    }

    static boolean intersect(int i, int j, long[] x1, long[] y1, long[] x2, long[] y2) {
        return Math.max(x1[i], x1[j]) <= Math.min(x2[i], x2[j]) &&
               Math.max(y1[i], y1[j]) <= Math.min(y2[i], y2[j]);
    }

