        int start = N;
        int end = N + 1;

        long INF = Long.MAX_VALUE / 4;
        long[][] w = new long[V][V];

        for (int i = 0; i < V; i++) {
            Arrays.fill(w[i], INF);
            w[i][i] = 0;
        }

        for (int i = 0; i < N; i++) {
            long ds = pointRectDist(Xi, Yi, x1[i], y1[i], x2[i], y2[i]);
            long de = pointRectDist(Xf, Yf, x1[i], y1[i], x2[i], y2[i]);
            w[start][i] = w[i][start] = ds;
            w[end][i] = w[i][end] = de;
        }

        w[start][end] = w[end][start] = manhattan(Xi, Yi, Xf, Yf);

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                long d;
                if (intersect(i, j, x1, y1, x2, y2)) {
                    d = 0;
                } else {
                    d = rectDist(i, j, x1, y1, x2, y2);
                }
                w[i][j] = w[j][i] = d;
            }
        }

        long[] dist = new long[V];
        Arrays.fill(dist, INF);
        dist[start] = 0;

        boolean[] vis = new boolean[V];

        for (int it = 0; it < V; it++) {
            int u = -1;
            long best = INF;

            for (int i = 0; i < V; i++) {
                if (!vis[i] && dist[i] < best) {
                    best = dist[i];
                    u = i;
                }
