            if (u == -1) break;
            vis[u] = true;

            for (int v = 0; v < V; v++) {
                if (!vis[v] && w[u][v] < INF) {
                    long nd = dist[u] + w[u][v];
                    if (nd < dist[v]) {
                        dist[v] = nd;
                    }
                }
            }
        }

        System.out.println(dist[end]);
    }
}
